import fs from 'fs';
import path from 'path';
import zlib from 'zlib';

const expectedBase = '0.30.4';
const targetVersion = '0.31.0';
const root = process.cwd();
const files = {"IS_Riadenie_odboru_v0.31.0_NETWORK_DISCOVERY.sql":"","NETWORK_DISCOVERY_0.31.md":"","README.md":"","README_NASADENIE_0.31.txt":"","RELEASE_NOTES.md":"","RELEASE_NOTES_0.31.md":"","collector/README.md":"","collector/config.example.json":"","collector/cvti_asset_collector.py":"","collector/run-collector.ps1":"H4sIAEKNd2oC/ytILErM1YguLinKzEuPVXHOz0vLTFewVVDSi0kGs/WyivPzlDS5VFyLivKLHJNLMvPzAopS01KLUvOSU0Eqg0vyC5S4CipLMvLzFIDaykoy4xOLi1NL4pPzc3JSk0vyi/QKKhV0dSEGKkAt4QIATADpdHsAAAA=","collector/run-collector.sh":"H4sIAEKNd2oC/1NW1E/KzNMvzuAqTi1R0E0t5XL293PzdLdVUqk2tNLV00/Oz0vLTNfLKs7Pq1XiSq1ITVYoqCzJyM8zVgBKlpVkxicWA7XGJ+fn5KQml+QX6RVUKujqQrQpKKlAjFPiAgAhBxRjaQAAAA==","package.json":"","src/data/seed.json":"","src/lib/assetImport.ts":"","src/lib/discoveryCloud.ts":"","src/lib/storage.ts":"","src/types.ts":"","src/views/AssetDiscovery.css":"","src/views/AssetDiscovery.tsx":"","src/views/Cmdb.tsx":"","supabase/migration_network_discovery_v031.sql":""};

function readJson(file) { try { return JSON.parse(fs.readFileSync(file, 'utf8')); } catch { return null; } }
function stamp() { return new Date().toISOString().replace(/[:.]/g, '-'); }
function fail(message, code = 1) { console.error('ERROR:', message); process.exit(code); }

const pkgPath = path.join(root, 'package.json');
if (!fs.existsSync(pkgPath)) fail('Spusti installer v koreni projektu.');
const pkg = readJson(pkgPath);
if (pkg?.name !== 'is-riadenie-odboru') fail('Tento priecinok nevyzera ako projekt is-riadenie-odboru.');
const current = String(pkg?.version || '');
if (current !== expectedBase && current !== targetVersion) console.log(`UPOZORNENIE: installer je testovany pre ${expectedBase} -> ${targetVersion}. Aktualna verzia: ${current || 'nezistena'}.`);

console.log(`IS Riadenie odboru - upgrade na v${targetVersion}`);
const backupRoot = path.join(root, `backup-before-v0310-${stamp()}`);
fs.mkdirSync(backupRoot, { recursive: true });
let written = 0, backedUp = 0;
for (const [rel, encoded] of Object.entries(files)) {
  const destination = path.join(root, rel);
  if (fs.existsSync(destination)) {
    const backup = path.join(backupRoot, rel);
    fs.mkdirSync(path.dirname(backup), { recursive: true });
    fs.copyFileSync(destination, backup);
    backedUp += 1;
  }
  fs.mkdirSync(path.dirname(destination), { recursive: true });
  fs.writeFileSync(destination, zlib.gunzipSync(Buffer.from(encoded, 'base64')));
  console.log('WRITE', rel);
  written += 1;
}
for (const cache of ['dist', '.vite', path.join('node_modules', '.vite')]) {
  const full = path.join(root, cache);
  if (fs.existsSync(full)) { fs.rmSync(full, { recursive: true, force: true }); console.log('CLEAR', cache); }
}
const installed = readJson(pkgPath);
if (String(installed?.version) !== targetVersion) fail('Kontrola verzie zlyhala.', 2);
const cmdb = fs.readFileSync(path.join(root, 'src/views/Cmdb.tsx'),'utf8');
const discovery = fs.readFileSync(path.join(root, 'src/views/AssetDiscovery.tsx'),'utf8');
const cloud = fs.readFileSync(path.join(root, 'src/lib/discoveryCloud.ts'),'utf8');
const collector = fs.readFileSync(path.join(root, 'collector/cvti_asset_collector.py'),'utf8');
const sql = fs.readFileSync(path.join(root, 'IS_Riadenie_odboru_v0.31.0_NETWORK_DISCOVERY.sql'),'utf8');
if (!cmdb.includes("['discovery','Network Discovery']")) fail('Network Discovery tab chyba.',3);
if (!discovery.includes('TOTAL ASSET INVENTORY') || !discovery.includes('Print Fleet')) fail('AssetDiscovery UI chyba.',4);
if (!cloud.includes("ingest_discovery") && !cloud.includes('discovery_devices')) fail('Discovery cloud vrstva chyba.',5);
if (!collector.includes('RFC1918') || !collector.includes('ingest_discovery_batch')) fail('Collector chyba alebo je nekompletny.',6);
if (!sql.includes('create table if not exists public.discovery_devices') || !sql.includes('ingest_discovery_batch')) fail('Discovery SQL chyba.',7);
console.log('');
console.log(`VERIFIED: v${targetVersion} Network Discovery je nainstalovane.`);
console.log(`Suborov zapisanych: ${written}, zalohovanych: ${backedUp}.`);
console.log('Zaloha:', backupRoot);
console.log('POZOR: pred pouzitim discovery spusti v Supabase IS_Riadenie_odboru_v0.31.0_NETWORK_DISCOVERY.sql.');
console.log('Potom vytvor collector v Asset management -> Network Discovery -> Collectory.');
